export default function (input) {
  const now = new Date(input.now);
  const lagos = new Date((isNaN(now.getTime()) ? new Date() : now).getTime() + 3600 * 1000);
  return { date: lagos.toISOString().slice(0, 10) };
}

function naira(n) { return 'NGN ' + Number(n).toLocaleString('en-NG', { minimumFractionDigits: 0, maximumFractionDigits: 2 }); }
function latestByReference(rows) {
  const by = {};
  for (const r of rows || []) {
    if (!r || !r.reference) continue;
    const seen = by[r.reference];
    if (!seen || String(r.happened_at || '') >= String(seen.happened_at || '')) by[r.reference] = r;
  }
  return Object.keys(by).map(function (k) { return by[k]; });
}
export default function (input) {
  let gross = 0, fees = 0, settled = 0, count = 0, unsettledKnown = 0;
  for (const s of latestByReference(input.rows)) {
    if (!s.approved) continue;
    const a = Number(s.amount); if (!isFinite(a)) continue;
    count += 1; gross += a;
    const f = Number(s.fee); if (isFinite(f)) fees += f;
    if (s.settled !== undefined && s.settled !== null && s.settled !== '') { const n = Number(s.settled); if (isFinite(n)) settled += n; }
    else { unsettledKnown += 1; settled += a - (isFinite(f) ? f : 0); }
  }
  const round = function (n) { return Math.round(n * 100) / 100; };
  const balance = input.balance_kobo === undefined || input.balance_kobo === null ? null : Number(input.balance_kobo) / 100;
  const lines = [input.business_name + ' OPay, ' + input.date + ': ' + count + ' payment(s), ' + naira(gross) + ' taken, ' + naira(fees) + ' in fees, ' + naira(settled) + ' settled to you.'];
  if (unsettledKnown > 0) lines.push(unsettledKnown + ' payment(s) carried no settlement figure; amount less fee was used.');
  if (balance !== null && isFinite(balance)) lines.push('OPay balance now: ' + naira(balance) + '.');
  if (count === 0) lines[0] = input.business_name + ' OPay, ' + input.date + ': no payments recorded today.';
  return { gross: round(gross), fees: round(fees), settled: round(settled), count: count, balance: balance, message: lines.join('\n') };
}
